def click_btn(text, scope='body'):
    """按**按钮文字**点（块工具条/抽屉里的按钮没有 id）—— `scope` 是 CSS 选择器。"""
    expr = (f"[...document.querySelectorAll({json.dumps(scope)})]"
            f".flatMap(r=>[...r.querySelectorAll('button')])"
            f".filter(b=>b.offsetParent!==null)"
            f".find(b=>b.innerText.trim()==={json.dumps(text)})")
    return click(expr, text)


def type_into(expr, text):
    """先清空再打（`Input.insertText` 会追加，不清空就会打成长串）。"""
    _fn('js')(f"""(() => {{const el={expr}; el.focus();
      const d=Object.getOwnPropertyDescriptor(el.__proto__,'value').set;
      d.call(el,''); el.dispatchEvent(new Event('input',{{bubbles:true}}));}})()""")
    time.sleep(0.15)
    _fn('cdp')("Input.insertText", text=text)
    time.sleep(0.25)
    return _fn('js')(f"{expr}.value")


